package in.smartcampus;
import jakarta.servlet.*;import jakarta.servlet.http.*;import jakarta.servlet.annotation.*;import java.io.*;import java.sql.*;import java.time.*;
@WebServlet("/book") public class BookingServlet extends HttpServlet {
 protected void doPost(HttpServletRequest q,HttpServletResponse r)throws IOException,ServletException {HttpSession s=q.getSession(false);if(s==null||s.getAttribute("userId")==null){r.sendRedirect(q.getContextPath()+"/login");return;}try{int rid=Integer.parseInt(q.getParameter("resourceId"));LocalDate date=LocalDate.parse(q.getParameter("bookingDate"));LocalTime start=LocalTime.parse(q.getParameter("startTime")),end=LocalTime.parse(q.getParameter("endTime"));String purpose=q.getParameter("purpose");if(!end.isAfter(start)||!date.isAfter(LocalDate.now().minusDays(1))||purpose==null||purpose.isBlank())throw new IllegalArgumentException();try(Connection c=DB.get()){c.setAutoCommit(false);try(PreparedStatement check=c.prepareStatement("SELECT COUNT(*) FROM bookings WHERE resource_id=? AND booking_date=? AND status IN ('PENDING','APPROVED') AND start_time < ? AND end_time > ?")){check.setInt(1,rid);check.setDate(2,Date.valueOf(date));check.setTime(3,Time.valueOf(end));check.setTime(4,Time.valueOf(start));try(ResultSet rs=check.executeQuery()){rs.next();if(rs.getInt(1)>0){c.rollback();r.sendRedirect(q.getContextPath()+"/resources?error=That+time+slot+conflicts+with+an+existing+request");return;}}}try(PreparedStatement ps=c.prepareStatement("INSERT INTO bookings(user_id,resource_id,booking_date,start_time,end_time,purpose,status) VALUES(?,?,?,?,?,?,'PENDING')")){ps.setInt(1,(Integer)s.getAttribute("userId"));ps.setInt(2,rid);ps.setDate(3,Date.valueOf(date));ps.setTime(4,Time.valueOf(start));ps.setTime(5,Time.valueOf(end));ps.setString(6,purpose.trim());ps.executeUpdate();}c.commit();}r.sendRedirect(q.getContextPath()+"/bookings?msg=Booking+request+submitted");}catch(IllegalArgumentException e){r.sendRedirect(q.getContextPath()+"/resources?error=Please+check+the+booking+details");}catch(SQLException e){throw new ServletException(e);}}
}